using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns an emoji for the given country. Returns an empty string on failure. Can be called synchronously
    /// </summary>
    public Task<TdLib.TdApi.Objects.Text> GetCountryFlagEmojiAsync(string countryCode = default)
    {

           using var activity =  StartCallActivity("GetCountryFlagEmojiAsync", typeof(GetCountryFlagEmoji).FullName ?? "GetCountryFlagEmojiAsync");

           try
           {
             return client.GetCountryFlagEmojiAsync(countryCode);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
